#!/usr/bin/env python3
"""Real MVC HR/payroll acceptance on a disposable localhost synthetic database only.
No browser execution, customer data, SQL Server, deployment or external connections.
"""
import re
from datetime import date, timedelta
from decimal import Decimal, ROUND_HALF_UP
from enterprise_http_fixture import Fixture, Forms

with Fixture('hr') as f:
    maker=f.login(1); reviewer=f.login(1,reviewer=True); outsider=f.login(2)
    for path in ['/HRPayroll','/HRPayroll/attendance','/HRPayroll/leave','/HRPayroll/policies','/HRPayroll/register','/HRPayroll/calculate','/HRPayroll/me']:
        f.page(maker,path)
    company=f.scalar("SELECT Id FROM Companies WHERE Slug='demo-farm-1'")
    branch=f.scalar('SELECT Id FROM Branches WHERE CompanyId=? AND Name=?',(company,'Demo Branch 1'))
    first=date.today().replace(day=1)
    previous=(first-timedelta(days=1)).replace(day=1)
    end=previous-timedelta(days=1); start=end.replace(day=1)
    employment=end-timedelta(days=1)
    form=f.form(maker,'/HRPayroll/staff','/HRPayroll/staff')
    fields={'Code':'HTTP-HR-TEST','Name':'HTTP FICTIONAL employee','JobTitle':'Synthetic ended employment','StartDate':employment.isoformat(),'EndDate':end.isoformat(),'Active':'false'}
    no_csrf=dict(form['fields']);no_csrf.update(fields);no_csrf.pop('__RequestVerificationToken',None)
    bad=maker.request('/HRPayroll/staff',fields=no_csrf)
    f.check('Staff POST requires antiforgery',bad.status==400)
    invalid=maker.submit(form,{**fields,'Name':''})
    f.check('Staff validation preserves input and creates no row',invalid.status==200 and 'HTTP-HR-TEST' in invalid.text and f.scalar("SELECT COUNT(*) FROM HRPayrollStaff WHERE Code='HTTP-HR-TEST'")==0)
    response=maker.submit(form,fields)
    f.check('Create ended staff through real form',response.status==302,'HTTP '+str(response.status)+'; '+str(re.findall(r'<li>(.*?)</li>',response.text,re.S)))
    sid=f.scalar("SELECT Id FROM HRPayrollStaff WHERE Code='HTTP-HR-TEST'")
    rate=f.form(maker,f'/HRPayroll/rates/{sid}','/HRPayroll/rates')
    response=maker.submit(rate,{'DailyRate':'100.125','OvertimeHourlyRate':'20.125','ReviewNote':'HTTP FICTIONAL reviewed rates'})
    f.check('Set protected pay rates through form',response.status==302)
    attendance=f.form(maker,f'/HRPayroll/attendance?staffId={sid}','/HRPayroll/attendance')
    values={'Entry.StaffId':sid,'Entry.Date':end.isoformat(),'Entry.PaidDays':'1','Entry.OvertimeHours':'2','Entry.Note':'HTTP fictional attendance'}
    response=maker.submit(attendance,values)
    f.check('Create attendance through real form',response.status==302)
    html=f.page(maker,f'/HRPayroll/attendance?staffId={sid}').text
    edit=next(x for x in Forms(html).forms if x['action']=='/HRPayroll/attendance' and int(x['fields'].get('Entry.Id','0') or 0)>0)
    response=maker.submit(edit,{'Entry.PaidDays':'0.5','Entry.Note':'Reviewed half day correction'})
    f.check('Attendance edit accepts original version',response.status==302)
    stale=maker.submit(edit,{'Entry.PaidDays':'1','Entry.Note':'Stale overwrite'})
    f.check('Stale attendance shows actionable error without overwrite',stale.status==200 and 'record changed' in stale.text.lower() and Decimal(str(f.scalar('SELECT PaidDays FROM HRPayrollAttendance WHERE StaffId=?',(sid,))))==Decimal('.5'))
    leave=f.form(maker,f'/HRPayroll/leave?staffId={sid}','/HRPayroll/leave')
    response=maker.submit(leave,{'Entry.StaffId':sid,'Entry.From':employment.isoformat(),'Entry.Through':employment.isoformat(),'Entry.Paid':'true','Entry.Reason':'HTTP FICTIONAL paid day'})
    f.check('Create pending leave through form',response.status==302)
    lid=f.scalar('SELECT Id FROM HRPayrollLeaves WHERE StaffId=?',(sid,))
    action=f'/HRPayroll/leave/{lid}/review'
    response=maker.submit(f.form(maker,f'/HRPayroll/leave?staffId={sid}',action),{'approve':'true','note':'Attempt self approval'})
    f.check('Same requester cannot approve leave',response.status==403)
    response=reviewer.submit(f.form(reviewer,f'/HRPayroll/leave?staffId={sid}',action),{'approve':'true','note':'HTTP FICTIONAL independent review'})
    f.check('Different reviewer approves requested paid leave',response.status==302 and f.scalar('SELECT Status FROM HRPayrollLeaves WHERE Id=?',(lid,))=='Approved')
    policy=f.form(maker,'/HRPayroll/policies','/HRPayroll/policies')
    response=maker.submit(policy,{'Entry.Name':'HTTP FICTIONAL daily payroll policy','Entry.PayBasis':'Daily','Entry.MonthlyProrationMode':'NotApplicable','Entry.MonthlyFixedUnits':'0','Entry.CapMonthlyPaidUnits':'false','Entry.Currency':'BDT','Entry.CurrencyDecimals':'2','Entry.EffectiveFrom':start.isoformat(),'Entry.EffectiveThrough':end.isoformat(),'Entry.DeductionPercent':'5','Entry.EmployerContributionPercent':'3','Entry.JurisdictionAndBasis':'HTTP FICTIONAL test contract and rates; not legal advice or statutory defaults.','Entry.ExpenseAccount':'6100','Entry.PayableAccount':'2300','Entry.DeductionAccount':'2310','Entry.EmployerExpenseAccount':'6110','Entry.EmployerPayableAccount':'2320'})
    f.check('Propose explicit payroll policy through real form',response.status==302)
    pid=f.scalar("SELECT Id FROM HRPayrollPolicies WHERE Name='HTTP FICTIONAL daily payroll policy'")
    action=f'/HRPayroll/policies/{pid}/review'
    response=reviewer.submit(f.form(reviewer,'/HRPayroll/policies',action),{'note':'HTTP FICTIONAL exact policy reviewed','confirm':'true'})
    f.check('Independent policy review through real form',response.status==302 and f.scalar('SELECT Reviewed FROM HRPayrollPolicies WHERE Id=?',(pid,))==1)
    response=maker.submit(f.form(maker,'/HRPayroll/calculate','/HRPayroll/calculate'),{'Entry.Reference':'HTTP-HR-RUN','Entry.PolicyId':pid,'Entry.PeriodStart':start.isoformat()})
    f.check('Calculate reviewable payroll through real form',response.status==302)
    rid=f.scalar("SELECT Id FROM HRPayrollRuns WHERE Reference='HTTP-HR-RUN'")
    detail=f'/HRPayroll/register/{rid}';f.page(maker,detail)
    row=f.query('SELECT BasePay,OvertimePay,GrossPay,Deductions,NetPay,EmployerContribution FROM HRPayrollLines WHERE RunId=?',(rid,))[0]
    f.check('Exact payroll arithmetic for daily pay leave and overtime',[Decimal(str(v)) for v in row]==[Decimal('150.19'),Decimal('40.25'),Decimal('190.44'),Decimal('9.52'),Decimal('180.92'),Decimal('5.71')],str(row))
    approve=f'/HRPayroll/register/{rid}/approve'
    response=maker.submit(f.form(maker,detail,approve),{'note':'Attempt same-calculator approval','confirm':'true'})
    f.check('Calculator cannot approve own payroll',response.status==403)
    response=reviewer.submit(f.form(reviewer,detail,approve),{'note':'HTTP FICTIONAL all lines and sources reviewed','confirm':'true'})
    f.check('Independent payroll approval through real form',response.status==302)
    post=f'/HRPayroll/register/{rid}/post';posting=f.form(reviewer,detail,post)
    response=reviewer.submit(posting,{'postingDate':end.isoformat()})
    f.check('Post reviewed payroll accrual through real form',response.status==302 and f.scalar('SELECT Status FROM HRPayrollRuns WHERE Id=?',(rid,))=='Posted')
    vid=f.scalar('SELECT VoucherId FROM HRPayrollRuns WHERE Id=?',(rid,));lines=f.query('SELECT Debit,Credit FROM VoucherLines WHERE VoucherId=?',(vid,))
    f.check('Posted payroll GL balances exactly',sum(Decimal(str(x[0])) for x in lines)==sum(Decimal(str(x[1])) for x in lines)==Decimal('196.15'))
    repeat=reviewer.submit(posting,{'postingDate':end.isoformat()})
    feedback=f.page(reviewer,detail)
    f.check('Repeated posting gives feedback and no duplicate voucher',repeat.status==302 and 'record changed' in feedback.text.lower() and f.scalar("SELECT COUNT(*) FROM Vouchers WHERE Reference='PAYROLL-HTTP-HR-RUN'")==1)
    lineid=f.scalar('SELECT Id FROM HRPayrollLines WHERE RunId=?',(rid,))
    reviewerid=f.scalar("SELECT Id FROM AspNetUsers WHERE Email='farmreviewer1@example.invalid'")
    link=f.form(maker,f'/HRPayroll/identity/{sid}',f'/HRPayroll/identity/{sid}')
    response=maker.submit(link,{'UserId':reviewerid,'Confirm':'true'})
    f.check('Protected exact verified account link through form',response.status==302 and f.scalar('SELECT IdentityUserId FROM HRPayrollStaff WHERE Id=?',(sid,))==reviewerid,'HTTP '+str(response.status)+'; '+str(re.findall(r'<li>(.*?)</li>',response.text,re.S)))
    own=f.page(reviewer,'/HRPayroll/me');slip=f.page(reviewer,f'/HRPayroll/me/payslip/{lineid}')
    f.check('Linked employee sees own posted payslip', 'HTTP-HR-RUN' in own.text and '180.92' in slip.text and 'does not confirm' in slip.text)
    forbidden=maker.request(f'/HRPayroll/me/payslip/{lineid}')
    f.check('Own payslip route rejects another employee line ID',forbidden.status in (400,403,404,409) and '180.92' not in forbidden.text,'HTTP '+str(forbidden.status))
    wrong=outsider.request(detail)
    f.check('Other company cannot read payroll details',wrong.status in (400,403,404,409) and 'HTTP FICTIONAL employee' not in wrong.text,'HTTP '+str(wrong.status))
    f.check('Payroll accrual does not create a money transfer',f.scalar("SELECT COUNT(*) FROM FinancePayments WHERE Reference LIKE 'HTTP-HR%'")==0)
    f.check('Posted payroll audit is present exactly once',f.scalar("SELECT COUNT(*) FROM Audits WHERE Action='Payroll.Post' AND Reference LIKE '%HTTP-HR-RUN%'")==1)
    self_form=f.form(maker,'/HRPayroll/me','/HRPayroll/me/leave')
    response=maker.submit(self_form,{'StaffId':sid,'From':date.today().isoformat(),'Through':date.today().isoformat(),'Paid':'false','Reason':'HTTP SELF ONLY forged staff ID ignored'})
    owner=f.scalar("SELECT Id FROM AspNetUsers WHERE Email='farmdemo1@example.invalid'")
    own_staff=f.scalar('SELECT Id FROM HRPayrollStaff WHERE IdentityUserId=?',(owner,))
    f.check('Employee own-leave form ignores forged staff ID and derives ownership',response.status==302 and f.scalar("SELECT StaffId FROM HRPayrollLeaves WHERE Reason='HTTP SELF ONLY forged staff ID ignored'")==own_staff and own_staff!=sid)

    # A second, older closed employment period exercises Monthly through the actual MVC controls.
    monthly_end=start-timedelta(days=1);monthly_start=monthly_end.replace(day=1);monthly_join=monthly_end-timedelta(days=1)
    response=maker.submit(f.form(maker,'/HRPayroll/staff','/HRPayroll/staff'),{'Code':'HTTP-MONTHLY','Name':'HTTP FICTIONAL monthly employee','JobTitle':'Synthetic monthly employment','StartDate':monthly_join.isoformat(),'EndDate':monthly_end.isoformat(),'Active':'false'})
    f.check('Create monthly-contract staff through MVC',response.status==302)
    monthly_staff=f.scalar("SELECT Id FROM HRPayrollStaff WHERE Code='HTTP-MONTHLY'")
    response=maker.submit(f.form(maker,f'/HRPayroll/rates/{monthly_staff}','/HRPayroll/rates'),{'PayBasis':'Monthly','DailyRate':'0','MonthlySalary':'3100','OvertimeHourlyRate':'0','ReviewNote':'HTTP FICTIONAL explicit monthly salary'})
    f.check('Save separate monthly salary through MVC',response.status==302)
    for workday,units in [(monthly_join,'1'),(monthly_end,'0')]:
        response=maker.submit(f.form(maker,f'/HRPayroll/attendance?staffId={monthly_staff}','/HRPayroll/attendance'),{'Entry.StaffId':monthly_staff,'Entry.Date':workday.isoformat(),'Entry.PaidDays':units,'Entry.OvertimeHours':'0','Entry.Note':'HTTP monthly paid or unpaid day'})
        f.check('Record explicit monthly paid units '+workday.isoformat(),response.status==302)
    response=maker.submit(f.form(maker,'/HRPayroll/policies','/HRPayroll/policies'),{'Entry.Name':'HTTP FICTIONAL monthly policy','Entry.PayBasis':'Monthly','Entry.MonthlyProrationMode':'ActualCalendarDays','Entry.MonthlyFixedUnits':'0','Entry.CapMonthlyPaidUnits':'true','Entry.Currency':'BDT','Entry.CurrencyDecimals':'2','Entry.EffectiveFrom':monthly_start.isoformat(),'Entry.EffectiveThrough':monthly_end.isoformat(),'Entry.DeductionPercent':'0','Entry.EmployerContributionPercent':'0','Entry.JurisdictionAndBasis':'HTTP FICTIONAL explicitly reviewed actual-calendar denominator and cap. Zero test contributions are intentional, not statutory advice.','Entry.ExpenseAccount':'6100','Entry.PayableAccount':'2300','Entry.DeductionAccount':'2310','Entry.EmployerExpenseAccount':'6110','Entry.EmployerPayableAccount':'2320'})
    f.check('Propose Monthly actual-calendar policy through MVC',response.status==302)
    monthly_policy=f.scalar("SELECT Id FROM HRPayrollPolicies WHERE Name='HTTP FICTIONAL monthly policy'")
    response=reviewer.submit(f.form(reviewer,'/HRPayroll/policies',f'/HRPayroll/policies/{monthly_policy}/review'),{'note':'Reviewed actual calendar denominator, cap and explicit zero rates','confirm':'true'})
    f.check('Approve monthly formula independently through MVC',response.status==302)
    response=maker.submit(f.form(maker,'/HRPayroll/calculate','/HRPayroll/calculate'),{'Entry.Reference':'HTTP-MONTHLY-RUN','Entry.PolicyId':monthly_policy,'Entry.PeriodStart':monthly_start.isoformat()})
    f.check('Calculate monthly payroll through MVC',response.status==302)
    monthly_run=f.scalar("SELECT Id FROM HRPayrollRuns WHERE Reference='HTTP-MONTHLY-RUN'")
    result=f.query('SELECT PayBasis,MonthlySalary,ProrationMode,ProrationDenominator,PaidUnitsUsed,BasePay FROM HRPayrollLines WHERE RunId=?',(monthly_run,))[0]
    expected=(Decimal('3100')/Decimal(monthly_end.day)).quantize(Decimal('.01'),rounding=ROUND_HALF_UP)
    f.check('Monthly payslip snapshots exact formula denominator salary and paid units',result[0]=='Monthly' and Decimal(str(result[1]))==3100 and result[2]=='ActualCalendarDays' and Decimal(str(result[3]))==monthly_end.day and Decimal(str(result[4]))==1 and Decimal(str(result[5]))==expected,str(result))
    monthly_detail=f'/HRPayroll/register/{monthly_run}'
    response=reviewer.submit(f.form(reviewer,monthly_detail,f'{monthly_detail}/approve'),{'note':'HTTP reviewed monthly salary and single paid day','confirm':'true'})
    f.check('Approve calculated monthly payroll through MVC',response.status==302)
    response=reviewer.submit(f.form(reviewer,monthly_detail,f'{monthly_detail}/post'),{'postingDate':monthly_end.isoformat()})
    f.check('Post monthly accrual through MVC',response.status==302 and f.scalar('SELECT Status FROM HRPayrollRuns WHERE Id=?',(monthly_run,))=='Posted')

    # Mixed contractual bases coexist in one unique branch/month run with separate historical versions.
    mixed_end=monthly_start-timedelta(days=1);mixed_start=mixed_end.replace(day=1);mixed_staff=[]
    for code,basis,daily,salary in [('HTTP-MIX-D','Daily','100','0'),('HTTP-MIX-M','Monthly','0','3100')]:
        response=maker.submit(f.form(maker,'/HRPayroll/staff','/HRPayroll/staff'),{'Code':code,'Name':'HTTP FICTIONAL '+basis+' mixed employee','JobTitle':'Synthetic mixed contract','StartDate':mixed_end.isoformat(),'EndDate':mixed_end.isoformat(),'Active':'false'})
        f.check('Create mixed '+basis+' staff through MVC',response.status==302)
        employee=f.scalar('SELECT Id FROM HRPayrollStaff WHERE Code=?',(code,));mixed_staff.append(employee)
        response=maker.submit(f.form(maker,f'/HRPayroll/rates/{employee}','/HRPayroll/rates'),{'PayBasis':basis,'DailyRate':daily,'MonthlySalary':salary,'OvertimeHourlyRate':'0','EffectiveFrom':mixed_start.isoformat(),'ReviewNote':'HTTP FICTIONAL explicit effective '+basis+' contract'})
        f.check('Save effective '+basis+' contract through MVC',response.status==302)
        response=maker.submit(f.form(maker,f'/HRPayroll/attendance?staffId={employee}','/HRPayroll/attendance'),{'Entry.StaffId':employee,'Entry.Date':mixed_end.isoformat(),'Entry.PaidDays':'1','Entry.OvertimeHours':'0','Entry.Note':'Explicit mixed paid day'})
        f.check('Save mixed '+basis+' attendance through MVC',response.status==302)
    response=maker.submit(f.form(maker,'/HRPayroll/policies','/HRPayroll/policies'),{'Entry.Name':'HTTP FICTIONAL Mixed policy','Entry.PayBasis':'Mixed','Entry.MonthlyProrationMode':'ActualCalendarDays','Entry.MonthlyFixedUnits':'0','Entry.CapMonthlyPaidUnits':'false','Entry.Currency':'BDT','Entry.CurrencyDecimals':'2','Entry.EffectiveFrom':mixed_start.isoformat(),'Entry.EffectiveThrough':mixed_end.isoformat(),'Entry.DeductionPercent':'0','Entry.EmployerContributionPercent':'0','Entry.JurisdictionAndBasis':'HTTP FICTIONAL Mixed Daily and Monthly policy with explicit actual-calendar monthly denominator and no cap.','Entry.ExpenseAccount':'6100','Entry.PayableAccount':'2300','Entry.DeductionAccount':'2310','Entry.EmployerExpenseAccount':'6110','Entry.EmployerPayableAccount':'2320'})
    f.check('Propose explicit Mixed policy through MVC',response.status==302)
    mixed_policy=f.scalar("SELECT Id FROM HRPayrollPolicies WHERE Name='HTTP FICTIONAL Mixed policy'")
    response=reviewer.submit(f.form(reviewer,'/HRPayroll/policies',f'/HRPayroll/policies/{mixed_policy}/review'),{'note':'Reviewed both contract bases and monthly denominator','confirm':'true'})
    f.check('Approve Mixed policy independently through MVC',response.status==302)
    response=maker.submit(f.form(maker,'/HRPayroll/calculate','/HRPayroll/calculate'),{'Entry.Reference':'HTTP-MIXED-RUN','Entry.PolicyId':mixed_policy,'Entry.PeriodStart':mixed_start.isoformat()})
    f.check('Calculate both contractual bases in one run through MVC',response.status==302)
    mixed_run=f.scalar("SELECT Id FROM HRPayrollRuns WHERE Reference='HTTP-MIXED-RUN'")
    mixed_rows=f.query('SELECT PayBasis,BasePay,CompensationVersion,CompensationEffectiveFrom,StaffId FROM HRPayrollLines WHERE RunId=? ORDER BY StaffId',(mixed_run,))
    monthly_expected=(Decimal('3100')/Decimal(mixed_end.day)).quantize(Decimal('.01'),rounding=ROUND_HALF_UP)
    f.check('Mixed run retains own basis amount and effective compensation snapshot',len(mixed_rows)==2 and mixed_rows[0][0]=='Daily' and Decimal(str(mixed_rows[0][1]))==100 and mixed_rows[1][0]=='Monthly' and Decimal(str(mixed_rows[1][1]))==monthly_expected and all(x[2]==1 and x[3]==mixed_start.isoformat() for x in mixed_rows),str(mixed_rows))
    f.check('Mixed run contains each employee once',len({x[4] for x in mixed_rows})==2)
    mixed_detail=f'/HRPayroll/register/{mixed_run}'
    response=reviewer.submit(f.form(reviewer,mixed_detail,f'{mixed_detail}/approve'),{'note':'Independently reviewed daily and monthly line snapshots','confirm':'true'})
    f.check('Approve mixed payroll independently through MVC',response.status==302)
    response=reviewer.submit(f.form(reviewer,mixed_detail,f'{mixed_detail}/post'),{'postingDate':mixed_end.isoformat()})
    f.check('Post mixed contractual payroll once through MVC',response.status==302 and f.scalar('SELECT Status FROM HRPayrollRuns WHERE Id=?',(mixed_run,))=='Posted')
    mixed_voucher=f.scalar('SELECT VoucherId FROM HRPayrollRuns WHERE Id=?',(mixed_run,))
    totals=f.query('SELECT Debit,Credit FROM VoucherLines WHERE VoucherId=?',(mixed_voucher,))
    f.check('Mixed accrual balances both exact line totals',sum(Decimal(str(x[0])) for x in totals)==sum(Decimal(str(x[1])) for x in totals)==100+monthly_expected)
    locked_rate=f.form(maker,f'/HRPayroll/rates/{mixed_staff[0]}','/HRPayroll/rates')
    response=maker.submit(locked_rate,{'DailyRate':'999','EffectiveFrom':mixed_start.isoformat(),'ReviewNote':'Attempt prohibited historical change'})
    f.check('Posted month rejects retroactive contractual rewrite with usable error',response.status==200 and 'approved or posted payroll' in response.text.lower() and f.scalar('SELECT COUNT(*) FROM HRPayrollCompensations WHERE StaffId=?',(mixed_staff[0],))==1)
